using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    // Technical namespaces the business layers must not touch directly.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Text.Json", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    private static readonly string[] BusinessLayers = ["Domain", "Application"];

    public static TheoryData<string> Layers => new(BusinessLayers);

    private static Assembly AssemblyOf(string layer) => layer == "Domain" ? Domain : Application;

    [Theory]
    [MemberData(nameof(Layers))]
    public void Business_layers_do_not_use_technical_namespaces(string layer)
    {
        var result = Types.InAssembly(AssemblyOf(layer))
            .ShouldNot().HaveDependencyOnAny(TechnicalNamespaces)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Theory]
    [MemberData(nameof(Layers))]
    public void Business_layers_do_not_depend_on_infrastructure(string layer)
    {
        var result = Types.InAssembly(AssemblyOf(layer))
            .ShouldNot().HaveDependencyOn("PaymentAuthorization.Infrastructure")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Domain_does_not_depend_on_application()
    {
        var result = Types.InAssembly(Domain)
            .ShouldNot().HaveDependencyOn("PaymentAuthorization.Application")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(TestResult result) =>
        "Layer violation in: " + string.Join(", ", result.FailingTypeNames ?? []);
}
